'use strict';
let preparationBusy=false,pieceDetailReturn=null,leaderboardRequest=0,rankRequest=0,cpuScoreTimer=null,cpuScoreBusy=false,cpuScorePending=false,cpuLastTeam=null,rankingPlayerReturn=null;
const prepEl=id=>document.getElementById(id);
function shownItem(raw){const base=KANJI_DATABASE.find(i=>i.char===raw.char),equippedReadings=Array.isArray(raw.equippedReadings)?raw.equippedReadings.slice():raw.ruby?[raw.ruby]:[];return {...base,...raw,jis:base.jis,level:raw.cpuControlled===true?KanjiLevels.clampCpu(raw.level):KanjiLevels.clamp(raw.level),ruby:equippedReadings[0]||'',equippedReadings,unlockedReadings:raw.unlockedReadings||equippedReadings};}
function pieceCards(box,items){
 items=KanjiTeamLinks.apply(items);box.replaceChildren();for(const raw of items){
  const compact=['prepare-enemies','prepare-allies'].includes(box.id),item=shownItem(raw),stats=getKanjiStats(item),button=document.createElement('button');button.className='prepare-piece'+(compact?' compact-piece':'');button.type='button';button.setAttribute('aria-label',`${item.char} Lv.${item.level}の詳細`);button.dataset.pieceChar=item.char;
  const top=document.createElement('span');top.className='piece-card-top'+(compact?'':' ranking-piece-top');const tier=document.createElement('span');tier.className='ranking-piece-tier';tier.textContent=`${getCharacterTypeLabel(item)}`;tier.title=tier.textContent;const level=document.createElement('span');level.className='ranking-piece-level';level.textContent=`Lv.${item.level}`;if(compact)top.append(level);else top.append(tier,level);
  const glyph=document.createElement('strong');glyph.className='kanji-font';glyph.textContent=item.char;glyph.style.color=KanjiRules.attributes[item.attr].light;
  const meta=document.createElement('span');meta.className='piece-card-meta';const attr=document.createElement('span');attr.className='piece-attribute';attr.textContent=ATTR_INFO[item.attr].name;attr.setAttribute('aria-label',ATTR_INFO[item.attr].name+'属性');attr.style.color=KanjiRules.attributes[item.attr].light;const strokes=document.createElement('span');strokes.textContent=`${KanjiTurnOrder.count(item)}画`;if(compact)meta.append(attr);else meta.append(attr,strokes);
  const ruby=document.createElement('small');ruby.className='piece-card-ruby';ruby.textContent=isSecretKanji(item)?'シークレット':`ルビ ${item.equippedReadings.length}個`;ruby.title=item.equippedReadings.join('／');
  const values=document.createElement('span');values.className='deck-stat-strip';for(const [label,key]of [['威力','power'],['重量','weight']]){const row=document.createElement('span'),title=document.createElement('span'),value=document.createElement('b');title.textContent=label;value.textContent=stats[key];value.className=key==='power'?'text-amber-400':'text-cyan-300';row.append(title,value);values.append(row);}
  const detail=document.createElement('small');detail.className='piece-detail-label';detail.textContent='詳細';if(compact)button.append(top,glyph,meta,detail);else button.append(top,glyph,meta,ruby,values,detail);if(!compact&&stats.teamLink){const badge=document.createElement('small');badge.className='team-link-badge';badge.textContent='連携：'+KanjiTeamLinks.effect(stats.teamLink);button.append(badge);}button.onclick=()=>openPieceDetail(item);box.append(button);
 }
}
window.openPieceDetail=raw=>{const item=shownItem(raw),stats=getKanjiStats(item),box=prepEl('piece-detail-content');pieceDetailReturn=document.activeElement;pausePlayerOverlay();box.replaceChildren();const chemical=window.KanjiElementCharacters?.get(item);if(chemical){const note=document.createElement('p');note.className='inventory-note';note.textContent=`元素文字：原子番号 ${chemical.number} ／ ${chemical.symbol} ／ ${chemical.reading}`;box.append(note);}prepEl('piece-detail-title').textContent=`「${item.char}」の詳細`;const title=document.createElement('p');title.className='piece-detail-summary';title.textContent=`${getCharacterTypeLabel(item)}・${ATTR_INFO[item.attr].name}属性・Lv.${item.level}・${KanjiTurnOrder.count(item)}画`;const values=document.createElement('p');values.textContent=`威力 ${stats.power}・重量 ${stats.weight}・機動 ${stats.speed}`;box.append(title,values);const reference=document.createElement('p');reference.className='variant-note';reference.textContent=KanjiReference.description(item.char)+(KanjiReference.variantLabel(item.char)?'・'+KanjiReference.variantLabel(item.char):'');box.append(reference);if(stats.teamLink){const p=document.createElement('p');p.className='team-link-badge';p.textContent=`連携「${stats.teamLink.name}」：${KanjiTeamLinks.effect(stats.teamLink)}`;box.append(p);}if(isSecretKanji(item)){const secret=document.createElement('p');secret.className='secret-chip';secret.textContent='シークレット・錬成限定（ルビなし）';box.append(secret);}const ability=(heading,a,kind)=>{const h=document.createElement('h3');h.textContent=heading;box.append(h);KanjiAbilityGuide.append(box,a,kind);};for(const a of stats.readingAbilities||KanjiReadAbilities.resolveAll(item)){const readings=item.equippedReadings.filter(r=>KanjiReadAbilities.resolve({...item,ruby:r})?.id===a.id);ability(`ルビ「${readings.join('・')}」・${a.name}`,a,'ruby');}const trait=KanjiTraits.get(item);if(trait)ability(`特殊文字・${trait.name}`,trait,'trait');const element=KanjiElements.get(item);if(element)ability(`${ATTR_INFO[item.attr].name}属性・${element.name}`,element,'element');appendUsageDetails(box,item.char);prepEl('modal-piece-detail').classList.remove('hidden');document.querySelector('#modal-piece-detail .editor-panel').scrollTop=0;document.querySelector('#modal-piece-detail button').focus();};
window.closePieceDetail=()=>{prepEl('modal-piece-detail').classList.add('hidden');if(typeof restoreCharacterBook==='function')restoreCharacterBook();restoreUsageRecords();resumePlayerEngine();if(pieceDetailReturn?.isConnected)pieceDetailReturn.focus();};
function editableSoloTeam(){return isPractice()&&practiceRun.kind!=='cpu-skill'&&!practiceRun.started||battleMode==='classic'||battleMode==='endless'&&endlessRun?.wave===1&&!endlessRun.started||battleMode==='special'&&specialChallenge?.streak===0&&!specialChallenge.started;}
function prepareSoloBattle(enemies,formation){soloPreview={mode:battleMode,difficulty:currentCpuDifficulty,enemies:enemies.map(i=>({...i,equippedReadings:getEquippedReadings(i).slice()})),formation:KanjiFormation.copy(formation),name:prepEl('cpu-name').textContent};soloBattlePending=true;isPlayerTurn=false;clearTimeout(cpuTurnTimer);cpuTurnTimer=null;runner.enabled=false;renderBattlePreparation();}
function renderBattlePreparation(){
 if(battleMode==='friend-cpu'){prepEl('battle-prepare').hidden=true;return;}
 prepEl('btn-prepare-close').hidden=!soloBattlePending||!['classic','endless','special'].includes(battleMode);
 if(typeof renderAutoBattleControls==='function')renderAutoBattleControls();
 renderPracticeBoardPreview();prepEl('btn-practice-back').hidden=!isPractice()||!soloBattlePending;prepEl('btn-prepare-edit').textContent=isPractice()?'編成を変更':'編成・ルビ・配置を変更';const room=friendRoom,network=room?.status==='preparing'||room?.status==='closed'&&battleMode==='friend';if(!network&&(battleMode==='friend'||!soloBattlePending)){prepEl('battle-prepare').hidden=true;return;}
 prepEl('battle-prepare').hidden=false;if(runner)runner.enabled=false;prepEl('prepare-title').textContent=network?'対人戦・対局の準備':isPractice()?'チャレンジ・挑戦の準備':battleMode==='endless'?'強敵連戦・対局の準備':battleMode==='special'?'特殊文字試練・対局の準備':'CPU戦・対局の準備';
 if(network){const me=room.side?room.guest:room.host,peer=room.side?room.host:room.guest,ready=!!room.ready[room.side];prepEl('prepare-rule').textContent=KanjiOnlineRules.label(room.ruleSet)+'：'+KanjiOnlineRules.description(room.ruleSet);paintPlayerName(prepEl('prepare-peer-name'),peer.profile);prepEl('prepare-peer-rp').textContent=room.mode==='online'?`対人RP ${room.peerOnlineStats.rating}`:'フレンド対戦';prepEl('prepare-self-rp').textContent=room.mode==='online'?`対人RP ${room.onlineStats.rating}`:'';if(peer.hidden){prepEl('prepare-enemies').replaceChildren();const note=document.createElement('p');note.className='inventory-note';note.textContent='相手の編成・ルビ・配置は双方の準備完了後に公開';prepEl('prepare-enemies').append(note);}else pieceCards(prepEl('prepare-enemies'),peer.items);pieceCards(prepEl('prepare-allies'),me.items);prepEl('prepare-note').textContent=room.mode==='online'?'相手の編成は双方の準備完了後に公開。双方がスタートを押すと対局開始。編成を変更すると双方のスタートを取り消します。部屋の準備時間は5分です。':'編成は非公開。双方が準備完了になると同時に確定して対局開始。変更する場合は自分の準備を取り消してください。準備時間は5分です。';prepEl('prepare-status').textContent=`あなた：${ready?'準備完了':'編成中'} ／ 相手：${room.ready[1-room.side]?'準備完了':'編成中'}`;prepEl('btn-battle-start').textContent=ready?'準備を取り消す':room.mode==='online'?'スタート':'準備完了';prepEl('btn-prepare-edit').disabled=preparationBusy||friendBusy||room.mode!=='online'&&ready;prepEl('btn-prepare-room').hidden=room.mode==='online'&&!room.departed;
 }else{if(!soloPreview)return;const team=isPractice()&&practiceRun.kind==='cpu-skill'?practiceRun.team:isPractice()?KanjiPlayRecords.prepareTeam(practiceRun.id,currentPracticeTeam(),gameState.practiceShooter):editableSoloTeam()?gameState.deck.map(id=>gameState.inventory.find(i=>i.instanceId===id)).filter(Boolean):startingBattleTeam();prepEl('prepare-rule').textContent=isPractice()?practiceChallenge().name+'・'+KanjiPlayRecords.levelLabel(practiceRun.id):battleMode==='classic'?'CPU対戦・'+{normal:'通常',hard:'強敵',boss:'漢字王'}[currentCpuDifficulty]:battleMode==='endless'?`強敵連戦・第${endlessRun.wave}戦`:`${specialChallenge.name}・相手Lv.${specialChallenge.level}`;prepEl('prepare-peer-name').textContent=soloPreview.name;prepEl('prepare-peer-rp').textContent='相手の文字をタップして能力を確認';prepEl('prepare-self-rp').textContent=`段位ポイント ${gameState.rating}`;pieceCards(prepEl('prepare-enemies'),soloPreview.enemies);pieceCards(prepEl('prepare-allies'),team.map(i=>({...i,equippedReadings:getEquippedReadings(i)})));prepEl('prepare-note').textContent=isPractice()?practiceChallenge().condition+(practiceRun.kind==='cpu-skill'?'。所持文字・育成・段位ポイントに関係なく挑戦。自己ベストのみ更新。経験値・文の変動なし。':practiceChallenge().rank?'。初回昇格条件の達成を記録。段位ポイント・経験値の変動なし。':'。初回報酬のみ・段位と経験値は変動しません。'):editableSoloTeam()?'相手を確認してから編成できます。スタートを押すまで対局は進みません。':'連勝中は開始時の編成を使用します。相手を確認してスタートしてください。';if(battleMode==='special')prepEl('prepare-note').textContent=specialChallenge.hint+' 相手の編成・ルビ・配置は固定。追加目標は全員生還と'+specialChallenge.shotTarget+'発以内の勝利です。';prepEl('prepare-status').textContent=isPractice()?KanjiPlayRecords.condition(practiceRun.id,currentPracticeTeam(),KanjiTurnOrder.count):'';prepEl('btn-battle-start').textContent='スタート';prepEl('btn-prepare-edit').disabled=!editableSoloTeam();prepEl('btn-prepare-room').hidden=true;}
 prepEl('btn-battle-start').disabled=preparationBusy||friendBusy||!!room?.departed||isPractice()&&!!KanjiPlayRecords.condition(practiceRun.id,currentPracticeTeam(),KanjiTurnOrder.count);if(room?.departed){prepEl('prepare-status').textContent='相手が退出しました。「部屋から退出」で退出し、新しい対戦を準備できます。';prepEl('btn-prepare-edit').disabled=true;}
}
window.editPreparedTeam=async()=>{if(preparationBusy)return;if(friendRoom?.status==='preparing'){onlineEditor=friendRoom.mode==='online';await openFriendDeckEditor();return;}if(!soloBattlePending||!editableSoloTeam())return;if(isPractice()){openPracticeDeck('battle');return;}preparationEditing=true;prepEl('btn-deck-start').textContent='編成を確定して対局前に戻る';switchTab('deck');};
window.startPreparedBattle=async()=>{
 if(preparationBusy)return;const room=friendRoom;
 if(room?.status==='preparing'){preparationBusy=true;renderBattlePreparation();try{acceptFriendRoom(await playerApi(`/api/friends/rooms/${room.code}/ready`,'POST',{revision:room.revision,lineupRevision:room.lineupRevision,round:room.round,ready:!room.ready[room.side]}),false);startFriendPolling();}catch(error){try{acceptFriendRoom(await playerApi(`/api/friends/rooms/${room.code}`),false);}catch{}prepEl('prepare-status').textContent=error.message;}finally{preparationBusy=false;renderBattlePreparation();}return;}
 if(!soloBattlePending||!soloPreview||battleMode==='friend')return;if(isPractice()&&!preparePracticeStart())return;const team=gameState.deck.map(id=>gameState.inventory.find(i=>i.instanceId===id)).filter(Boolean);if(!isPractice()&&(!team.length||battleMode==='special'&&team.length!==3)){showToast('出撃する文字を編成してください。');return;}if(editableSoloTeam()){if(battleMode==='endless'){endlessRun.team=team.map(i=>({...i,equippedReadings:getEquippedReadings(i).slice()}));endlessRun.formation=KanjiFormation.copy(getActiveFormation());}if(battleMode==='special'){specialChallenge.team=team.map(i=>({...i,equippedReadings:getEquippedReadings(i).slice()}));specialChallenge.formation=KanjiFormation.copy(getActiveFormation());}}preparationEditing=false;prepEl('btn-deck-start').textContent='この編成で出撃';if(battleMode==='endless')endlessRun.started=true;if(battleMode==='special')specialChallenge.started=true;resetBattle(true,true);if(battleMode==='classic')cpuLastTeam=playerBodies.map(b=>({char:b.gameData.char,level:b.gameData.level,equippedReadings:b.gameData.equippedReadings.slice()}));
};
function rankingScore(entry,rule){if(rule==='cpu-skill')return `${entry.clearedStages} / 5課題・${KanjiCpuSkill.formatScore(entry.score,entry.season||cpuSkillSeason)}点`;return rule==='endless'?`${entry.wins}連勝・${entry.kills}体${entry.estimated?'以上':''}撃破`:rule==='trial'?`${entry.wins}連勝`:`${entry.rating} ${rule==='cpu'?'段位ポイント':'対人RP'}`;}
window.openRankingPlayer=(entry,rule,trigger)=>{
 rankingPlayerReturn=trigger||document.activeElement;pausePlayerOverlay();const box=prepEl('ranking-player-content');box.replaceChildren();const heading=document.createElement('div');heading.className='ranking-profile-heading';const icon=document.createElement('span');icon.className='player-avatar large';const text=document.createElement('div'),name=document.createElement('h3'),score=document.createElement('p');name.dataset.rankingName='';paintPlayerName(name,entry.profile);score.textContent=`${entry.position}位・${rankingScore(entry,rule)}`;text.append(name,score);heading.append(icon,text);box.append(heading);paintPlayerAvatar(icon,entry.profile);
 const kind=document.createElement('p');kind.textContent=prepEl('leaderboard-rule').querySelector(`option[value="${rule}"]`)?.textContent||'ランキング';box.append(kind);
 if(Number.isInteger(entry.wins)&&!['endless','trial'].includes(rule)){const results=document.createElement('p');results.textContent=`${entry.wins}勝・${entry.losses}敗・${entry.draws}分`;box.append(results);}
 const honor=KanjiHonors.get(entry.profile.honorId);if(honor){const frame=document.createElement('p');frame.textContent='装飾枠：'+honor.name;box.append(frame);}
 const title=document.createElement('h4');title.textContent=rule==='cpu-skill'?'全員共通の貸出文字':['endless','trial'].includes(rule)?'最高記録時の使用文字':'直近の対戦で使用した文字';box.append(title);if(entry.items.length){const cards=document.createElement('div');cards.className='prepare-pieces';pieceCards(cards,entry.items);box.append(cards);}else{const note=document.createElement('p');note.textContent='使用文字はまだ記録されていません。';box.append(note);}
 const note=document.createElement('p');note.className='inventory-note';note.textContent='文字をタップすると、レベル・装備ルビ・能力を確認できます。';box.append(note);prepEl('modal-ranking-player').classList.remove('hidden');prepEl('modal-ranking-player').querySelector('.editor-panel').scrollTop=0;prepEl('modal-ranking-player').querySelector('button').focus();
};
window.closeRankingPlayer=()=>{prepEl('modal-ranking-player').classList.add('hidden');resumePlayerEngine();if(rankingPlayerReturn?.isConnected)rankingPlayerReturn.focus();};
window.loadLeaderboard=async()=>{
 const request=++leaderboardRequest,rule=prepEl('leaderboard-rule').value,challenge=rule==='endless'||rule==='trial';prepEl('leaderboard-list').replaceChildren();prepEl('leaderboard-status').textContent='ランキングを読み込み中…';
 prepEl('leaderboard-guide').textContent=rule==='cpu-skill'?'シーズンごとの共通条件で挑戦。自己ベストは端末（ブラウザ）ごとに保存し、各課題の合計で競います。合計点で順位を決め、同点なら早い撃破を優先します。そこまで同じなら同順位。段位ポイント・プレイ回数・開始日は順位に影響しません。':'ランキング・対人RPは端末（ブラウザ）ごとに記録します。'+(challenge?(rule==='endless'?'連勝数を優先し、同じ連勝数なら撃破数で順位が決まります。':'最高連勝数で順位が決まります。'):'')+'上位10人まで表示します。名前でプレイヤーの詳細、文字で使用コマの能力を確認できます。';
 prepEl('cpu-skill-season-label').hidden=rule!=='cpu-skill';try{if(rule==='cpu-skill'){await initializeCpuSkillSeasons();if(typeof syncCpuSkillBestRecords==='function')await syncCpuSkillBestRecords();if(request!==leaderboardRequest)return;}const season=cpuSkillSeason;const result=await playerApi('/api/leaderboard?rule='+rule+(rule==='cpu-skill'?'&season='+season:''));if(request!==leaderboardRequest)return;const box=prepEl('leaderboard-list'),entries=result.entries.slice(0,10);for(const raw of entries){
  // Keep each ranking identity separate from the editable local player profile.
  const entry=structuredClone(raw);Object.freeze(entry.profile);const row=document.createElement('article');row.className='leaderboard-row';const who=document.createElement('button');who.type='button';who.className='leaderboard-player leaderboard-profile-button';who.dataset.rankingPosition=String(entry.position);who.setAttribute('aria-label',`${entry.position}位 ${entry.profile.name}の詳細を見る`);const icon=document.createElement('span');icon.className='player-avatar';const name=document.createElement('strong');name.dataset.rankingName='';paintPlayerName(name,entry.profile,`${entry.position}位 ${entry.profile.name}`);const score=document.createElement('span');score.className='leaderboard-score';score.textContent=rankingScore(entry,rule);who.append(icon,name,score);who.onclick=()=>openRankingPlayer(entry,rule,who);row.append(who);
  if(entry.items.length){const cards=document.createElement('div');cards.className='prepare-pieces';pieceCards(cards,entry.items);row.append(cards);}else{const note=document.createElement('p');note.className='inventory-note';note.textContent=challenge?'過去の記録の編成は未記録です。次の最高記録更新から表示されます。':'使用文字は次の対戦から記録されます。';row.append(note);}box.append(row);paintPlayerAvatar(icon,entry.profile);
 }prepEl('leaderboard-status').textContent=entries.length?`上位${entries.length}人 / 最大10人`:rule==='cpu-skill'?'このシーズンの登録記録はまだありません。CPU腕試しに勝つと記録が登録されます。':'まだ対戦記録がありません。';}catch(error){if(request===leaderboardRequest)prepEl('leaderboard-status').textContent=error.message+' 更新ボタンで再確認できます。';}
};
window.loadMatchesHub=async()=>{const request=++rankRequest;try{const session=await playerApi('/api/session');if(!session.authenticated){prepEl('rank-online-rp').textContent='対人RP：ログインして確認';return;}const [balanced,free]=await Promise.all([playerApi('/api/online/stats?rule=balanced'),playerApi('/api/online/stats?rule=free')]);if(request===rankRequest)prepEl('rank-online-rp').textContent=`対人RP：統一 ${balanced.rating} ／ 自由 ${free.rating}`;}catch{prepEl('rank-online-rp').textContent='対人RP：接続後に確認できます';}};
window.loadRankHub=()=>{renderPromotionTrials();loadLeaderboard();loadMatchesHub();initializeChallengeRankings();};
function queueCpuScore(){if(!cpuLastTeam)return;gameState.cpuRanking={pending:true,items:cpuLastTeam};cpuScorePending=true;clearTimeout(cpuScoreTimer);cpuScoreTimer=setTimeout(syncCpuScore,400);}
async function syncCpuScore(){if(cpuScoreBusy||!cpuScorePending||!cpuLastTeam)return;cpuScoreBusy=true;cpuScorePending=false;const snapshot={rating:gameState.rating,items:cpuLastTeam};try{const session=await playerApi('/api/session');if(!session.authenticated){cpuScorePending=true;return;}await ensurePlayerProfile();await playerApi('/api/cpu/score','POST',snapshot);if(gameState.rating===snapshot.rating&&gameState.cpuRanking){gameState.cpuRanking.pending=false;gameState.cpuRanking.scopeVersion=1;saveState();}}catch{cpuScorePending=true;}finally{cpuScoreBusy=false;if(cpuScorePending&&gameState.rating!==snapshot.rating)queueCpuScore();}}
window.addEventListener('online',()=>{if(cpuScorePending)syncCpuScore();});

window.showFriendBoard=()=>{switchTab('battle');renderBattlePreparation();};

function restoreCpuRanking(){const record=gameState.cpuRanking;if(record&&(record.pending||record.scopeVersion!==1)&&Array.isArray(record.items)&&record.items.length){cpuLastTeam=record.items;cpuScorePending=true;syncCpuScore();}}
window.addEventListener('load',restoreCpuRanking);
